CREATE TABLE `cites` (
  `cited_paper_id` varchar(255) NOT NULL,
  `citing_paper_id` varchar(255) NOT NULL,
  PRIMARY KEY (`cited_paper_id`,`citing_paper_id`),
  FOREIGN KEY (`cited_paper_id`) REFERENCES `webpage` (`webpage_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  FOREIGN KEY (`citing_paper_id`) REFERENCES `webpage` (`webpage_id`) ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE TABLE `content` (
  `webpage_id` varchar(255) NOT NULL,
  `word_cited_id` varchar(255) NOT NULL,
  PRIMARY KEY (`webpage_id`,`word_cited_id`),
  FOREIGN KEY (`webpage_id`) REFERENCES `webpage` (`webpage_id`) ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE TABLE `webpage` (
  `webpage_id` varchar(255) NOT NULL PRIMARY KEY,
  `class_label` varchar(255) DEFAULT NULL
);
